"""
SOS - School of Skills | Management Portal (Streamlit version)

Combines and simplifies two earlier drafts into one working app:
  - the small OOP sketch (SOS / Courses / Student classes) with the
    fixed indentation, a corrected `add_paid_fees`, and class-level
    course registry idea kept
  - the full Tkinter desktop app (course/student/faculty CRUD, JSON
    persistence, dashboard + reports), re-built with Streamlit instead
    of Tkinter for a much smaller amount of code

Run:
    pip install streamlit pandas
    streamlit run sos_management_portal.py

Login:
    Username: admin
    Password: sos2026
"""

import json
import os
import uuid
from abc import ABC
from dataclasses import asdict, dataclass, field

import pandas as pd
import streamlit as st

DATA_FILE = os.path.join(os.path.dirname(os.path.abspath(__file__)), "sos_data.json")

# Embedded SOS logo supplied by the user.
SOS_LOGO_B64 = """"""
SOS_LOGO_DATA = f"data:image/png;base64,{SOS_LOGO_B64}"


# =========================================================
# DOMAIN MODELS
# =========================================================
class SOS(ABC):
    """Base class holding the institution's identity."""
    name = "SCHOOL OF SKILLS"
    location = "CALICUT"
    starting_year = 2026

    @classmethod
    def details(cls):
        return {"Name": cls.name, "Location": cls.location, "Starting Year": cls.starting_year}


def new_id(prefix):
    return f"{prefix}_{uuid.uuid4().hex[:6]}"


@dataclass
class Course(SOS):
    id: str
    course_name: str
    duration: str
    fees: float
    faculty: str = ""
    seats: int = 0
    available: bool = True


@dataclass
class Student(SOS):
    id: str
    student_name: str
    phone: str
    age: int
    course_id: str
    fine: float = 0.0
    fees_paid: list = field(default_factory=list)  # list of payment amounts

    def total_paid(self):
        return sum(self.fees_paid)

    def add_paid_fees(self, amount):
        """Record a fee payment (this is what the pasted sketch left unfinished)."""
        self.fees_paid.append(float(amount))


@dataclass
class Faculty(SOS):
    id: str
    name: str
    subject: str = ""
    phone: str = ""
    slots: list = field(default_factory=list)

# =========================================================
# DATA STORE — JSON persistence + CRUD + simple business logic
# =========================================================
class DataStore:
    def __init__(self, path):
        self.path = path
        self.courses = []
        self.students = []
        self.faculty = []
        self.load()

    # ---- persistence ----
    def load(self):
        if os.path.exists(self.path):
            with open(self.path, "r", encoding="utf-8") as f:
                raw = json.load(f)
            self.courses = [Course(**c) for c in raw.get("courses", [])]
            self.students = [Student(**s) for s in raw.get("students", [])]
            self.faculty = [Faculty(**f) for f in raw.get("faculty", [])]
        else:
            self.seed()

    def save(self):
        data = {
            "courses": [asdict(c) for c in self.courses],
            "students": [asdict(s) for s in self.students],
            "faculty": [asdict(f) for f in self.faculty],
        }
        with open(self.path, "w", encoding="utf-8") as f:
            json.dump(data, f, indent=2)

    def seed(self):
        self.courses = [
            Course(new_id("crs"), "Full Stack Web Development", "6 Months", 35000, "Arjun Menon", 30, True),
            Course(new_id("crs"), "Digital Marketing Pro", "3 Months", 18000, "Fathima Rasheed", 40, True),
            Course(new_id("crs"), "UI/UX Design Bootcamp", "4 Months", 24000, "Nikhil Das", 25, True),
            Course(new_id("crs"), "Spoken English Mastery", "2 Months", 9000, "Ayesha Khan", 35, False),
        ]
        c1, c2, c3, _ = self.courses
        self.students = [
            Student(new_id("stu"), "Rahul Krishnan", "9895123456", 22, c1.id, 0, [20000, 5000]),
            Student(new_id("stu"), "Sneha Thomas", "9847012345", 24, c2.id, 200, [10000]),
            Student(new_id("stu"), "Mohammed Ashiq", "9645098765", 20, c3.id, 0, [24000]),
        ]
        self.faculty = [
            Faculty(new_id("fac"), "Arjun Menon", "Full Stack Development", "9876543210"),
            Faculty(new_id("fac"), "Fathima Rasheed", "Digital Marketing", "9765432109"),
            Faculty(new_id("fac"), "Nikhil Das", "UI/UX Design", "9654321098"),
        ]
        self.save()

    def reset(self):
        self.seed()

    # ---- lookups ----
    def course_by_id(self, cid):
        return next((c for c in self.courses if c.id == cid), None)

    def available_courses(self):
        return [c for c in self.courses if c.available]

    def search_courses(self, q):
        q = (q or "").lower()
        return [c for c in self.courses if q in c.course_name.lower()]

    def search_students(self, q):
        q = (q or "").lower()
        return [s for s in self.students if q in s.student_name.lower() or q in s.phone]

    def enrolled_count(self, course_id):
        return len([s for s in self.students if s.course_id == course_id])

    def due(self, student):
        course = self.course_by_id(student.course_id)
        fees = course.fees if course else 0
        return max(0, fees - student.total_paid()) + student.fine

    def total_revenue(self):
        return sum(s.total_paid() for s in self.students)

    def total_pending_dues(self):
        return sum(self.due(s) for s in self.students)

    # ---- CRUD ----
    def add_course(self, **data):
        self.courses.append(Course(id=new_id("crs"), **data))
        self.save()

    def delete_course(self, cid):
        self.courses = [c for c in self.courses if c.id != cid]
        self.save()

    def add_student(self, **data):
        self.students.append(Student(id=new_id("stu"), **data))
        self.save()

    def delete_student(self, sid):
        self.students = [s for s in self.students if s.id != sid]
        self.save()

    def add_faculty(self, **data):
        self.faculty.append(Faculty(id=new_id("fac"), **data))
        self.save()

    def delete_faculty(self, fid):
        self.faculty = [f for f in self.faculty if f.id != fid]
        self.save()


