if "store" not in st.session_state:
    st.session_state.store = DataStore(DATA_FILE)
if "authed" not in st.session_state:
    st.session_state.authed = False

store = st.session_state.store


def login_screen():
    st.markdown(
        f"""
        <div class="login-card">
            <img class="sos-login-logo" src="{SOS_LOGO_DATA}" alt="SOS School of Skills logo">
            <div class="sos-brand-title" style="text-align:center;">Management Portal</div>
            <div class="sos-brand-subtitle" style="text-align:center;">{SOS.location} · Secure Admin Access</div>
        </div>
        """,
        unsafe_allow_html=True,
    )
    st.write("")
    with st.form("login"):
        user = st.text_input("Username")
        pwd = st.text_input("Password", type="password")
        submitted = st.form_submit_button("Sign In")
    if submitted:
        if user == "admin" and pwd == "sos2026":
            st.session_state.authed = True
            st.rerun()
        else:
            st.error("Invalid username or password.")
    st.caption("Demo access — Username: admin   Password: sos2026")


if not st.session_state.authed:
    login_screen()
    st.stop()

